import os

RESOURCE_ROOT = os.path.realpath("/data/reports")

# maps a resource path to the user id allowed to read it
OWNERS = {
    "alice/summary.csv": "user_alice",
    "bob/summary.csv": "user_bob",
}

def read_resource(uri_path, requesting_user_id):
    candidate = os.path.realpath(os.path.join(RESOURCE_ROOT, uri_path))
    inside_sandbox = candidate == RESOURCE_ROOT or candidate.startswith(RESOURCE_ROOT + os.sep)
    if not inside_sandbox:
        raise PermissionError("resource not found")

    owner = OWNERS.get(uri_path)
    if owner is None or owner != requesting_user_id:
        raise PermissionError("resource not found")

    with open(candidate, "r") as f:
        return f.read()
